@property
def request_id(self):
    """ Request ID: the value of the header named by the
        ``request_id.header`` app config key, or a generated ID. """
    if 'bottle.request_id' not in self.environ:
        app = self.environ.get('bottle.app')
        name = app.config.get('request_id.header') if app else None
        key = 'HTTP_' + name.upper().replace('-', '_') if name else None
        self.environ['bottle.request_id'] = (key and self.environ.get(key)) or uuid.uuid4().hex
    return self.environ['bottle.request_id']

